/**
 * MUXARO Real Binary End-to-End Download & Preview Verification
 *
 * Verifies with authentic media generated by FFmpeg:
 * 1. Local video upload (POST /api/v1/media/upload) -> ffprobe stream extraction.
 * 2. Real video compression (CONVERT_FORMAT 480p) -> TurboFlow processing -> output artifact verified by ffprobe.
 * 3. Real audio extraction (EXTRACT_AUDIO MP3) -> TurboFlow processing -> playable MP3 verified by ffprobe.
 * 4. Binary delivery integrity:
 *    - Default download -> Content-Disposition: attachment, SHA-256 match, 0% corruption
 *    - Inline preview (?inline=1) -> Content-Disposition: inline
 *    - RFC 9110 Range request -> HTTP 206 Partial Content, Content-Range, Content-Length
 */

import { describe, it, before, after } from 'node:test';
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { type FastifyInstance } from 'fastify';

import { buildApp } from '../../apps/api/src/app.ts';

function ffprobeJson(filePath: string): any {
  const out = execFileSync(
    'ffprobe',
    ['-v', 'error', '-show_format', '-show_streams', '-of', 'json', filePath],
    { encoding: 'utf8', timeout: 15000 }
  );
  return JSON.parse(out);
}

async function sleep(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

describe('MUXARO Downloader - Real Binary E2E Execution & Delivery', () => {
  let app: FastifyInstance;
  let tmpDir: string;
  let sourceMp4Path: string;
  let sourceMp4Buffer: Buffer;

  before(async () => {
    app = await buildApp();
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'muxaro-binary-e2e-'));
    sourceMp4Path = path.join(tmpDir, 'source_sample_1080p.mp4');

    // Generate real 3-second 1080p H.264 / AAC video
    execFileSync(
      'ffmpeg',
      [
        '-y',
        '-f', 'lavfi', '-i', 'testsrc2=size=1920x1080:rate=30:duration=3',
        '-f', 'lavfi', '-i', 'sine=frequency=440:duration=3',
        '-c:v', 'libx264', '-preset', 'ultrafast', '-b:v', '3000k',
        '-c:a', 'aac', '-b:a', '128k',
        '-pix_fmt', 'yuv420p',
        sourceMp4Path,
      ],
      { stdio: 'pipe', timeout: 30000 }
    );

    sourceMp4Buffer = fs.readFileSync(sourceMp4Path);
    assert.ok(sourceMp4Buffer.length > 50000, 'Synthetic source MP4 must be generated');
  });

  after(async () => {
    await app.close();
    fs.rmSync(tmpDir, { recursive: true, force: true });
  });

  it('should stream-upload local MP4 and inspect with genuine ffprobe metadata', async () => {
    const uploadRes = await app.inject({
      method: 'POST',
      url: '/api/v1/media/upload',
      headers: {
        'content-type': 'application/octet-stream',
        'x-file-name': encodeURIComponent('source_sample_1080p.mp4'),
        authorization: 'Bearer usr_binary_tester_1',
      },
      payload: sourceMp4Buffer,
    });

    assert.strictEqual(uploadRes.statusCode, 200, 'Upload must return HTTP 200');
    const uploadJson = uploadRes.json();
    assert.strictEqual(uploadJson.success, true);
    const asset = uploadJson.data;

    assert.ok(asset.assetId || asset.id);
    assert.strictEqual(asset.container, 'mp4');
    assert.strictEqual(asset.fileSizeBytes, sourceMp4Buffer.length);
    assert.ok(asset.streams.length >= 2, 'Must have at least 1 video and 1 audio stream');

    const vStream = asset.streams.find((s: any) => s.type === 'VIDEO');
    assert.ok(vStream, 'Video stream must be detected');
    assert.strictEqual(vStream.width, 1920);
    assert.strictEqual(vStream.height, 1080);
  });

  it('should compress video to 480p and deliver verified binary with Range support', async () => {
    const userId = `usr_compress_${Date.now()}`;
    const idemKey = `idem_comp_${Date.now()}`;

    // 1. Upload
    const uploadRes = await app.inject({
      method: 'POST',
      url: '/api/v1/media/upload',
      headers: {
        'content-type': 'application/octet-stream',
        'x-file-name': encodeURIComponent('source_for_compress.mp4'),
        authorization: `Bearer ${userId}`,
      },
      payload: sourceMp4Buffer,
    });
    const assetId = uploadRes.json().data.assetId;

    // 2. Submit compression job
    const createRes = await app.inject({
      method: 'POST',
      url: '/api/v1/jobs',
      headers: {
        authorization: `Bearer ${userId}`,
        'idempotency-key': idemKey,
      },
      payload: {
        mediaAssetId: assetId,
        operation: 'CONVERT_FORMAT',
        targetFormat: 'mp4',
        targetResolution: '480p',
        streamCopy: false,
        title: 'Compressed 480p Clip',
        idempotencyKey: idemKey,
      },
    });

    assert.strictEqual(createRes.statusCode, 202);
    const jobId = createRes.json().data.jobId;

    // 3. Poll until READY
    let jobData: any = null;
    const startTime = Date.now();
    while (Date.now() - startTime < 60000) {
      const pollRes = await app.inject({
        method: 'GET',
        url: `/api/v1/jobs/${jobId}`,
        headers: { authorization: `Bearer ${userId}` },
      });
      assert.strictEqual(pollRes.statusCode, 200);
      const pollJson = pollRes.json();
      jobData = pollJson.data;
      if (jobData.status === 'READY' || jobData.status === 'FAILED') break;
      await sleep(350);
    }

    assert.strictEqual(jobData.status, 'READY', `Job must reach READY. Status: ${jobData.status}, error: ${JSON.stringify(jobData.error)}`);
    assert.ok(jobData.outputFilename);
    assert.ok(jobData.checksumSha256);

    // 4. Test download endpoint redirect (GET /api/v1/jobs/:id/download)
    const dlRedirectRes = await app.inject({
      method: 'GET',
      url: `/api/v1/jobs/${jobId}/download`,
      headers: { authorization: `Bearer ${userId}` },
    });
    assert.strictEqual(dlRedirectRes.statusCode, 302, 'Download route must redirect to signed download token');
    const signedDownloadUrl = dlRedirectRes.headers.location!;
    assert.ok(signedDownloadUrl.includes('/api/v1/download/'));

    // 5. Test default download delivery (attachment)
    const binaryRes = await app.inject({
      method: 'GET',
      url: signedDownloadUrl,
      headers: { authorization: `Bearer ${userId}` },
    });
    if (binaryRes.statusCode !== 200) {
      console.error('Binary download returned error:', binaryRes.statusCode, binaryRes.body);
    }
    assert.strictEqual(binaryRes.statusCode, 200);
    assert.strictEqual(binaryRes.headers['content-type'], 'video/mp4');
    assert.ok(binaryRes.headers['content-disposition']?.includes('attachment'));

    const downloadedBuf = binaryRes.rawPayload;
    assert.ok(downloadedBuf.length < sourceMp4Buffer.length, '480p compressed file must be smaller than 1080p source');

    // SHA-256 checksum match
    const actualSha = crypto.createHash('sha256').update(downloadedBuf).digest('hex');
    assert.strictEqual(actualSha, jobData.checksumSha256, 'Downloaded binary SHA-256 must match job checksum');

    // Save and verify with ffprobe
    const out480pPath = path.join(tmpDir, 'downloaded_480p.mp4');
    fs.writeFileSync(out480pPath, downloadedBuf);
    const probe = ffprobeJson(out480pPath);
    const vStream = probe.streams.find((s: any) => s.codec_type === 'video');
    assert.ok(vStream, 'Valid video stream required');
    assert.strictEqual(vStream.height, 480, 'Height must be scaled to 480');

    // 6. Test inline preview delivery (?inline=1)
    const inlineSeparator = signedDownloadUrl.includes('?') ? '&' : '?';
    const inlineRes = await app.inject({
      method: 'GET',
      url: `${signedDownloadUrl}${inlineSeparator}inline=1`,
      headers: { authorization: `Bearer ${userId}` },
    });
    assert.strictEqual(inlineRes.statusCode, 200);
    assert.ok(inlineRes.headers['content-disposition']?.includes('inline'), 'Must have Content-Disposition: inline');

    // 7. Test HTTP 206 Range request streaming
    const rangeRes = await app.inject({
      method: 'GET',
      url: signedDownloadUrl,
      headers: {
        authorization: `Bearer ${userId}`,
        range: 'bytes=0-1023',
      },
    });
    assert.strictEqual(rangeRes.statusCode, 206, 'Must return HTTP 206 Partial Content');
    assert.strictEqual(rangeRes.rawPayload.length, 1024);
    assert.ok(rangeRes.headers['content-range']?.startsWith('bytes 0-1023/'));
    assert.strictEqual(rangeRes.headers['accept-ranges'], 'bytes');
  });

  it('should extract MP3 audio and deliver playable audio file verified by ffprobe', async () => {
    const userId = `usr_audio_${Date.now()}`;
    const idemKey = `idem_audio_${Date.now()}`;

    // 1. Upload source video
    const uploadRes = await app.inject({
      method: 'POST',
      url: '/api/v1/media/upload',
      headers: {
        'content-type': 'application/octet-stream',
        'x-file-name': encodeURIComponent('source_for_audio.mp4'),
        authorization: `Bearer ${userId}`,
      },
      payload: sourceMp4Buffer,
    });
    const assetId = uploadRes.json().data.assetId;

    // 2. Submit audio extraction job
    const createRes = await app.inject({
      method: 'POST',
      url: '/api/v1/jobs',
      headers: {
        authorization: `Bearer ${userId}`,
        'idempotency-key': idemKey,
      },
      payload: {
        mediaAssetId: assetId,
        operation: 'EXTRACT_AUDIO',
        targetFormat: 'mp3',
        title: 'Extracted Soundtrack',
        idempotencyKey: idemKey,
      },
    });

    assert.strictEqual(createRes.statusCode, 202);
    const jobId = createRes.json().data.jobId;

    // 3. Poll until READY
    let jobData: any = null;
    const startTime = Date.now();
    while (Date.now() - startTime < 60000) {
      const pollRes = await app.inject({
        method: 'GET',
        url: `/api/v1/jobs/${jobId}`,
        headers: { authorization: `Bearer ${userId}` },
      });
      assert.strictEqual(pollRes.statusCode, 200);
      jobData = pollRes.json().data;
      if (jobData.status === 'READY' || jobData.status === 'FAILED') break;
      await sleep(350);
    }

    assert.strictEqual(jobData.status, 'READY');
    assert.strictEqual(jobData.targetFormat, 'mp3');

    // 4. Download signed binary
    const dlRedirectRes = await app.inject({
      method: 'GET',
      url: `/api/v1/jobs/${jobId}/download`,
      headers: { authorization: `Bearer ${userId}` },
    });
    assert.strictEqual(dlRedirectRes.statusCode, 302);
    const signedUrl = dlRedirectRes.headers.location!;

    const binaryRes = await app.inject({
      method: 'GET',
      url: signedUrl,
      headers: { authorization: `Bearer ${userId}` },
    });
    assert.strictEqual(binaryRes.statusCode, 200);
    assert.strictEqual(binaryRes.headers['content-type'], 'audio/mpeg');

    // Save and verify with ffprobe
    const outMp3Path = path.join(tmpDir, 'extracted_soundtrack.mp3');
    fs.writeFileSync(outMp3Path, binaryRes.rawPayload);
    const probe = ffprobeJson(outMp3Path);
    const aStream = probe.streams.find((s: any) => s.codec_type === 'audio');
    assert.ok(aStream, 'Extracted MP3 must have a valid audio stream');
    assert.strictEqual(aStream.codec_name, 'mp3');
    assert.ok(Number(probe.format.duration) > 2.5, 'Duration must match source video ~3s');
  });
});
